import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Container, Row, Col, Card, Spinner } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import './EventList.css';

const EventList = () => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  // ✅ Fetch events from backend
  const fetchEvents = async () => {
    const token = localStorage.getItem('accessToken');
    
    if (token) {
      try {
        const response = await axios.get('http://localhost:8000/api/events/available', {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
        setEvents(response.data);
      } catch (error) {
        console.error("❌ Error fetching events:", error.response?.data || error.message);
      } finally {
        setLoading(false);
      }
    } else {
      console.log("❌ No auth token found. Redirecting to login.");
      navigate('/login');
    }
  };

  useEffect(() => {
    fetchEvents();
  }, []);

  return (
    <Container className="mt-4">
      <h2 className="text-center mb-4">Available Events</h2>
      {loading ? (
        <div className="text-center">
          <Spinner animation="border" variant="info" />
        </div>
      ) : events.length > 0 ? (
        <Row>
          {events.map((event) => (
            <Col key={event._id} md={4} sm={6} xs={12} className="mb-4">
              <Card className="event-card">
                <div className="card-image-wrapper">
                  <Card.Img 
                    variant="top" 
                    src={event.image 
                      ? `http://localhost:8000${event.image}` 
                      : `https://source.unsplash.com/400x250/?event`
                    } 
                    alt={event.title} 
                  />
                  <div className="event-overlay">
                    <h5 className="event-title">{event.title}</h5>
                    <p className="event-description">{event.description}</p>
                    <p className="event-date">
                      {new Date(event.date).toLocaleDateString()}
                    </p>
                  </div>
                </div>
              </Card>
            </Col>
          ))}
        </Row>
      ) : (
        <p className="text-center">No events available at the moment.</p>
      )}
    </Container>
  );
};

export default EventList;
